<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageCreatedAtVO;

trait MessageCreatedAtAttributeHolder
{
    protected MessageCreatedAtVO|\DateTimeImmutable|null $createdAt = null;
    protected bool $createdAtAssigned = false;

    public function getCreatedAtOrDefault(MessageCreatedAtVO $createdAt): MessageCreatedAtVO
    {
        if ($this->createdAtAssigned) {
            \assert(null !== $this->createdAt);
            return MessageCreatedAtVO::from($this->createdAt);
        } else {
            return $createdAt;
        }
    }
    public function createdAt(MessageCreatedAtVO|\DateTimeImmutable $createdAt): static
    {
        $this->createdAt = $createdAt;
        $this->createdAtAssigned = true;
        return $this;
    }
    public function getCreatedAt(): ?\DateTimeImmutable
    {
        return $this->createdAt instanceof MessageCreatedAtVO ? $this->createdAt->value() : $this->createdAt;
    }
    public function isCreatedAtAssigned(): bool
    {
        return $this->createdAtAssigned;
    }
    public function writeCreatedAtTo(mixed $att): void
    {
        if ($this->createdAtAssigned) {
            \assert(null !== $this->createdAt);
            $att->createdAt($this->createdAt);
        }
    }
    public function readCreatedAtFrom(mixed $att): void
    {
        if ($att->isCreatedAtAssigned()) {
            $createdAt = $att->getCreatedAt();
            \assert(null !== $createdAt);
            $this->createdAt($createdAt);
        }
    }
    public function unsetCreatedAt(): static
    {
        $this->createdAtAssigned = false;
        return $this;
    }
    protected function withDefaultCreatedAt(): void
    {
        if ($this->createdAt === null) {
            $this->createdAt = 'now';
        }
    }
    protected function withAssertedCreatedAtRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->createdAtAssigned = $this->createdAtAssigned) {
            $value->createdAt = MessageCreatedAtVO::tryFrom($this->createdAt, $errorsList);
        }
    }
}
